using System;

// PROGRAM: Mengimplementasikan Algoritma Transfer Dana Berdasarkan Pseudocode
public enum TransferStatus { Sukses, SaldoTidakCukup, RekeningTujuanTidakAktif, NominalIlegal }

public class BankAccount
{
    public string Id { get; set; } = "";
    public decimal Saldo { get; set; }
    public bool IsAktif { get; set; }
}

public class TransferService
{
    public static TransferStatus EksekusiTransfer(BankAccount asal, BankAccount tujuan, decimal nominal)
    {
        // 1. Pre-condition check
        if (nominal <= 0) return TransferStatus.NominalIlegal;
        if (asal.Saldo < nominal) return TransferStatus.SaldoTidakCukup;
        if (!tujuan.IsAktif) return TransferStatus.RekeningTujuanTidakAktif;

        // 2. Eksekusi mutasi saldo
        asal.Saldo -= nominal;
        tujuan.Saldo += nominal;

        return TransferStatus.Sukses;
    }
}

public class Program
{
    public static void Main()
    {
        // Uji coba algoritma
        var accA = new BankAccount { Id = "ACC-01", Saldo = 500_000, IsAktif = true };
        var accB = new BankAccount { Id = "ACC-02", Saldo = 100_000, IsAktif = true };

        var hasil = TransferService.EksekusiTransfer(accA, accB, 200_000);
        Console.WriteLine($"Status Transfer: {hasil}");
        Console.WriteLine($"Saldo Akhir Pengirim: Rp {accA.Saldo:N0}");
        Console.WriteLine($"Saldo Akhir Penerima: Rp {accB.Saldo:N0}");
    }
}

