using System;

public class PrimeAlgorithm
{
    public static bool IsPrime(int n)
    {
        if (n <= 1) return false;
        if (n == 2 || n == 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;

        for (int i = 5; i * i <= n; i += 6)
        {
            if (n % i == 0 || n % (i + 2) == 0)
                return false;
        }

        return true;
    }

    public static void Main()
    {
        Console.WriteLine($"7 adalah prima: {IsPrime(7)}");
        Console.WriteLine($"10 adalah prima: {IsPrime(10)}");
    }
}
